19	package org.apache.hadoop.yarn.server.federation.policies.router;
20	
21	import java.util.Map;
22	
23	import org.apache.hadoop.yarn.api.records.ApplicationSubmissionContext;
24	import org.apache.hadoop.yarn.conf.YarnConfiguration;
25	import org.apache.hadoop.yarn.server.federation.policies.AbstractConfigurableFederationPolicy;
26	import org.apache.hadoop.yarn.server.federation.policies.dao.WeightedPolicyInfo;
27	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyException;
28	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyInitializationException;
29	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterIdInfo;
30	
31	/**
32	 * Base abstract class for {@link FederationRouterPolicy} implementations, that
33	 * provides common validation for reinitialization.
34	 */
35	public abstract class AbstractRouterPolicy extends
36	    AbstractConfigurableFederationPolicy implements FederationRouterPolicy {
37	
38	  @Override
39	  public void validate(WeightedPolicyInfo newPolicyInfo)
40	      throws FederationPolicyInitializationException {
41	    super.validate(newPolicyInfo);
42	    Map<SubClusterIdInfo, Float> newWeights =
43	        newPolicyInfo.getRouterPolicyWeights();
44	    if (newWeights == null || newWeights.size() < 1) {
45	      throw new FederationPolicyInitializationException(
46	          "Weight vector cannot be null/empty.");
47	    }
48	  }
49	
50	  public void validate(ApplicationSubmissionContext appSubmissionContext)
51	      throws FederationPolicyException {
52	
53	    if (appSubmissionContext == null) {
54	      throw new FederationPolicyException(
55	          "Cannot route an application with null context.");
56	    }
57	
58	    // if the queue is not specified we set it to default value, to be
59	    // compatible with YARN behavior.
60	    String queue = appSubmissionContext.getQueue();
61	    if (queue == null) {
62	      appSubmissionContext.setQueue(YarnConfiguration.DEFAULT_QUEUE_NAME);
63	    }
64	  }
65	
66	}
