    18	package org.apache.hadoop.yarn.server.federation.policies.router;
    19	
    20	import java.util.ArrayList;
    21	import java.util.Collections;
    22	import java.util.List;
    23	import java.util.Map;
    24	
    25	import org.apache.hadoop.yarn.api.records.ApplicationSubmissionContext;
    26	import org.apache.hadoop.yarn.exceptions.YarnException;
    27	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyInitializationContext;
    28	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyInitializationContextValidator;
    29	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyUtils;
    30	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyInitializationException;
    31	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterId;
    32	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterInfo;
    33	
    34	/**
    35	 * This {@link FederationRouterPolicy} pick a subcluster based on the hash of
    36	 * the job's queue name. Useful to provide a default behavior when too many
    37	 * queues exist in a system. This also ensures that all jobs belonging to a
    38	 * queue are mapped to the same sub-cluster (likely help with locality).
    39	 */
    40	public class HashBasedRouterPolicy extends AbstractRouterPolicy {
    41	
    42	  @Override
    43	  public void reinitialize(
    44	      FederationPolicyInitializationContext federationPolicyContext)
    45	      throws FederationPolicyInitializationException {
    46	    FederationPolicyInitializationContextValidator
    47	        .validate(federationPolicyContext, this.getClass().getCanonicalName());
    48	
    49	    // note: this overrides BaseRouterPolicy and ignores the weights
    50	    setPolicyContext(federationPolicyContext);
    51	  }
    52	
    53	  /**
    54	   * Simply picks from alphabetically-sorted active subclusters based on the
    55	   * hash of quey name. Jobs of the same queue will all be routed to the same
    56	   * sub-cluster, as far as the number of active sub-cluster and their names
    57	   * remain the same.
    58	   *
    59	   * @param appSubmissionContext the {@link ApplicationSubmissionContext} that
    60	   *          has to be routed to an appropriate subCluster for execution.
    61	   *
    62	   * @param blackListSubClusters the list of subClusters as identified by
    63	   *          {@link SubClusterId} to blackList from the selection of the home
    64	   *          subCluster.
    65	   *
    66	   * @return a hash-based chosen {@link SubClusterId} that will be the "home"
    67	   *         for this application.
    68	   *
    69	   * @throws YarnException if there are no active subclusters.
    70	   */
    71	  @Override
    72	  public SubClusterId getHomeSubcluster(
    73	      ApplicationSubmissionContext appSubmissionContext,
    74	      List<SubClusterId> blackListSubClusters) throws YarnException {
    75	
    76	    // throws if no active subclusters available
    77	    Map<SubClusterId, SubClusterInfo> activeSubclusters =
    78	        getActiveSubclusters();
    79	
    80	    FederationPolicyUtils.validateSubClusterAvailability(
    81	        new ArrayList<SubClusterId>(activeSubclusters.keySet()),
    82	        blackListSubClusters);
    83	
    84	    if (blackListSubClusters != null) {
    85	
    86	      // Remove from the active SubClusters from StateStore the blacklisted ones
    87	      for (SubClusterId scId : blackListSubClusters) {
    88	        activeSubclusters.remove(scId);
    89	      }
    90	    }
    91	
    92	    validate(appSubmissionContext);
    93	
    94	    int chosenPosition = Math.abs(
    95	        appSubmissionContext.getQueue().hashCode() % activeSubclusters.size());
    96	
    97	    List<SubClusterId> list = new ArrayList<>(activeSubclusters.keySet());
    98	    Collections.sort(list);
    99	    return list.get(chosenPosition);
   100	  }
   101	
   102	}
