    24	import org.apache.hadoop.yarn.api.records.ApplicationSubmissionContext;
    25	import org.apache.hadoop.yarn.exceptions.YarnException;
    26	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyInitializationContext;
    27	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyUtils;
    28	import org.apache.hadoop.yarn.server.federation.policies.dao.WeightedPolicyInfo;
    29	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyException;
    30	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyInitializationException;
    31	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterId;
    32	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterIdInfo;
    33	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterInfo;
    34	import org.codehaus.jettison.json.JSONException;
    35	import org.codehaus.jettison.json.JSONObject;
    36	
    37	/**
    38	 * This implements a simple load-balancing policy. The policy "weights" are
    39	 * binary 0/1 values that enable/disable each sub-cluster, and the policy peaks
    40	 * the sub-cluster with the least load to forward this application.
    41	 */
    42	public class LoadBasedRouterPolicy extends AbstractRouterPolicy {
    43	
    44	  @Override
    45	  public void reinitialize(FederationPolicyInitializationContext policyContext)
    46	      throws FederationPolicyInitializationException {
    47	
    48	    // remember old policyInfo
    49	    WeightedPolicyInfo tempPolicy = getPolicyInfo();
    50	
    51	    // attempt new initialization
    52	    super.reinitialize(policyContext);
    53	
    54	    // check extra constraints
    55	    for (Float weight : getPolicyInfo().getRouterPolicyWeights().values()) {
    56	      if (weight != 0 && weight != 1) {
    57	        // reset to old policyInfo if check fails
    58	        setPolicyInfo(tempPolicy);
    59	        throw new FederationPolicyInitializationException(
    60	            this.getClass().getCanonicalName()
    61	                + " policy expects all weights to be either "
    62	                + "\"0\" or \"1\"");
    63	      }
    64	    }
    65	  }
    66	
    67	  @Override
    68	  public SubClusterId getHomeSubcluster(
    69	      ApplicationSubmissionContext appSubmissionContext,
    70	      List<SubClusterId> blacklist) throws YarnException {
    71	
    72	    // null checks and default-queue behavior
    73	    validate(appSubmissionContext);
    74	
    75	    Map<SubClusterId, SubClusterInfo> activeSubclusters =
    76	        getActiveSubclusters();
    77	
    78	    FederationPolicyUtils.validateSubClusterAvailability(
    79	        new ArrayList<SubClusterId>(activeSubclusters.keySet()), blacklist);
    80	
    81	    Map<SubClusterIdInfo, Float> weights =
    82	        getPolicyInfo().getRouterPolicyWeights();
    83	    SubClusterIdInfo chosen = null;
    84	    long currBestMem = -1;
    85	    for (Map.Entry<SubClusterId, SubClusterInfo> entry : activeSubclusters
    86	        .entrySet()) {
    87	      if (blacklist != null && blacklist.contains(entry.getKey())) {
    88	        continue;
    89	      }
    90	      SubClusterIdInfo id = new SubClusterIdInfo(entry.getKey());
    91	      if (weights.containsKey(id) && weights.get(id) > 0) {
    92	        long availableMemory = getAvailableMemory(entry.getValue());
    93	        if (availableMemory > currBestMem) {
    94	          currBestMem = availableMemory;
    95	          chosen = id;
    96	        }
    97	      }
    98	    }
    99	    if (chosen == null) {
   100	      throw new FederationPolicyException(
   101	          "Zero Active Subcluster with weight 1.");
   102	    }
   103	    return chosen.toId();
   104	  }
   105	
   106	  private long getAvailableMemory(SubClusterInfo value) throws YarnException {
   107	    try {
   108	      long mem = -1;
   109	      JSONObject obj = new JSONObject(value.getCapability());
   110	      mem = obj.getJSONObject("clusterMetrics").getLong("availableMB");
   111	      return mem;
   112	    } catch (JSONException j) {
   113	      throw new YarnException("FederationSubCluserInfo cannot be parsed", j);
   114	    }
   115	  }
