    18	package org.apache.hadoop.yarn.server.federation.policies.router;
    19	
    20	import java.util.ArrayList;
    21	import java.util.List;
    22	import java.util.Map;
    23	
    24	import org.apache.hadoop.yarn.api.records.ApplicationSubmissionContext;
    25	import org.apache.hadoop.yarn.exceptions.YarnException;
    26	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyUtils;
    27	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyException;
    28	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterId;
    29	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterIdInfo;
    30	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterInfo;
    31	
    32	/**
    33	 * This implements a policy that interprets "weights" as a ordered list of
    34	 * preferences among sub-clusters. Highest weight among active subclusters is
    35	 * chosen.
    36	 */
    37	public class PriorityRouterPolicy extends AbstractRouterPolicy {
    38	
    39	  @Override
    40	  public SubClusterId getHomeSubcluster(
    41	      ApplicationSubmissionContext appSubmissionContext,
    42	      List<SubClusterId> blacklist) throws YarnException {
    43	
    44	    // null checks and default-queue behavior
    45	    validate(appSubmissionContext);
    46	
    47	    Map<SubClusterId, SubClusterInfo> activeSubclusters =
    48	        getActiveSubclusters();
    49	
    50	    FederationPolicyUtils.validateSubClusterAvailability(
    51	        new ArrayList<SubClusterId>(activeSubclusters.keySet()), blacklist);
    52	
    53	    // This finds the sub-cluster with the highest weight among the
    54	    // currently active ones.
    55	    Map<SubClusterIdInfo, Float> weights =
    56	        getPolicyInfo().getRouterPolicyWeights();
    57	    SubClusterId chosen = null;
    58	    Float currentBest = Float.MIN_VALUE;
    59	    for (SubClusterId id : activeSubclusters.keySet()) {
    60	      SubClusterIdInfo idInfo = new SubClusterIdInfo(id);
    61	      if (blacklist != null && blacklist.contains(id)) {
    62	        continue;
    63	      }
    64	      if (weights.containsKey(idInfo) && weights.get(idInfo) > currentBest) {
    65	        currentBest = weights.get(idInfo);
    66	        chosen = id;
    67	      }
    68	    }
    69	    if (chosen == null) {
    70	      throw new FederationPolicyException(
    71	          "No Active Subcluster with weight vector greater than zero");
    72	    }
    73	
    74	    return chosen;
    75	  }
    76	
