    29	
    30	/**
    31	 * This {@link FederationRouterPolicy} simply rejects all incoming requests.
    32	 * This is useful to prevent applications running in a queue to be run anywhere
    33	 * in the federated cluster.
    34	 */
    35	public class RejectRouterPolicy extends AbstractRouterPolicy {
    36	
    37	  @Override
    38	  public void reinitialize(
    39	      FederationPolicyInitializationContext federationPolicyContext)
    40	      throws FederationPolicyInitializationException {
    41	    FederationPolicyInitializationContextValidator
    42	        .validate(federationPolicyContext, this.getClass().getCanonicalName());
    43	    setPolicyContext(federationPolicyContext);
    44	  }
    45	
    46	  /**
    47	   * The policy always reject requests.
    48	   *
    49	   * @param appSubmissionContext the {@link ApplicationSubmissionContext} that
    50	   *          has to be routed to an appropriate subCluster for execution.
    51	   *
    52	   * @param blackListSubClusters the list of subClusters as identified by
    53	   *          {@link SubClusterId} to blackList from the selection of the home
    54	   *          subCluster.
    55	   *
    56	   * @return (never).
    57	   *
    58	   * @throws YarnException (always) to prevent applications in this queue to be
    59	   *           run anywhere in the federated cluster.
    60	   */
    61	  @Override
    62	  public SubClusterId getHomeSubcluster(
    63	      ApplicationSubmissionContext appSubmissionContext,
    64	      List<SubClusterId> blackListSubClusters) throws YarnException {
    65	
    66	    // run standard validation, as error might differ
    67	    validate(appSubmissionContext);
    68	
    69	    throw new FederationPolicyException("The policy configured for this queue"
    70	        + " (" + appSubmissionContext.getQueue() + ") reject all routing "
    71	        + "requests by construction. Application "
    72	        + appSubmissionContext.getApplicationId()
    73	        + " cannot be routed to any RM.");
    74	  }
    75	
    76	}
