    18	package org.apache.hadoop.yarn.server.federation.policies.router;
    19	
    20	import java.util.ArrayList;
    21	import java.util.List;
    22	import java.util.Map;
    23	import java.util.Random;
    24	
    25	import org.apache.hadoop.yarn.api.records.ApplicationSubmissionContext;
    26	import org.apache.hadoop.yarn.exceptions.YarnException;
    27	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyInitializationContext;
    28	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyInitializationContextValidator;
    29	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyUtils;
    30	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyInitializationException;
    31	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterId;
    32	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterInfo;
    33	
    34	/**
    35	 * This simple policy picks at uniform random among any of the currently active
    36	 * subclusters. This policy is easy to use and good for testing.
    37	 *
    38	 * NOTE: this is "almost" subsumed by the {@code WeightedRandomRouterPolicy}.
    39	 * Behavior only diverges when there are active sub-clusters that are not part
    40	 * of the "weights", in which case the {@link UniformRandomRouterPolicy} send
    41	 * load to them, while {@code WeightedRandomRouterPolicy} does not.
    42	 */
    43	public class UniformRandomRouterPolicy extends AbstractRouterPolicy {
    44	
    45	  private Random rand;
    46	
    47	  public UniformRandomRouterPolicy() {
    48	    rand = new Random(System.currentTimeMillis());
    49	  }
    50	
    51	  @Override
    52	  public void reinitialize(FederationPolicyInitializationContext policyContext)
    53	      throws FederationPolicyInitializationException {
    54	    FederationPolicyInitializationContextValidator.validate(policyContext,
    55	        this.getClass().getCanonicalName());
    56	
    57	    // note: this overrides AbstractRouterPolicy and ignores the weights
    58	
    59	    setPolicyContext(policyContext);
    60	  }
    61	
    62	  /**
    63	   * Simply picks a random active subCluster to start the AM (this does NOT
    64	   * depend on the weights in the policy).
    65	   *
    66	   * @param appSubmissionContext the {@link ApplicationSubmissionContext} that
    67	   *          has to be routed to an appropriate subCluster for execution.
    68	   *
    69	   * @param blackListSubClusters the list of subClusters as identified by
    70	   *          {@link SubClusterId} to blackList from the selection of the home
    71	   *          subCluster.
    72	   *
    73	   * @return a randomly chosen subcluster.
    74	   *
    75	   * @throws YarnException if there are no active subclusters.
    76	   */
    77	  @Override
    78	  public SubClusterId getHomeSubcluster(
    79	      ApplicationSubmissionContext appSubmissionContext,
    80	      List<SubClusterId> blackListSubClusters) throws YarnException {
    81	
    82	    // null checks and default-queue behavior
    83	    validate(appSubmissionContext);
    84	
    85	    Map<SubClusterId, SubClusterInfo> activeSubclusters =
    86	        getActiveSubclusters();
    87	
    88	    List<SubClusterId> list = new ArrayList<>(activeSubclusters.keySet());
    89	
    90	    FederationPolicyUtils.validateSubClusterAvailability(list,
    91	        blackListSubClusters);
    92	
    93	    if (blackListSubClusters != null) {
    94	
    95	      // Remove from the active SubClusters from StateStore the blacklisted ones
    96	      for (SubClusterId scId : blackListSubClusters) {
    97	        list.remove(scId);
    98	      }
    99	    }
   100	
   101	    return list.get(rand.nextInt(list.size()));
   102	  }
   103	
   104	}
