    25	import org.apache.hadoop.yarn.api.records.ApplicationSubmissionContext;
    26	import org.apache.hadoop.yarn.exceptions.YarnException;
    27	import org.apache.hadoop.yarn.server.federation.policies.FederationPolicyUtils;
    28	import org.apache.hadoop.yarn.server.federation.policies.exceptions.FederationPolicyException;
    29	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterId;
    30	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterIdInfo;
    31	import org.apache.hadoop.yarn.server.federation.store.records.SubClusterInfo;
    32	
    33	/**
    34	 * This policy implements a weighted random sample among currently active
    35	 * sub-clusters.
    36	 */
    37	public class WeightedRandomRouterPolicy extends AbstractRouterPolicy {
    38	
    39	  @Override
    40	  public SubClusterId getHomeSubcluster(
    41	      ApplicationSubmissionContext appSubmissionContext,
    42	      List<SubClusterId> blacklist) throws YarnException {
    43	
    44	    // null checks and default-queue behavior
    45	    validate(appSubmissionContext);
    46	
    47	    Map<SubClusterId, SubClusterInfo> activeSubclusters =
    48	        getActiveSubclusters();
    49	
    50	    FederationPolicyUtils.validateSubClusterAvailability(
    51	        new ArrayList<SubClusterId>(activeSubclusters.keySet()), blacklist);
    52	
    53	    // note: we cannot pre-compute the weights, as the set of activeSubcluster
    54	    // changes dynamically (and this would unfairly spread the load to
    55	    // sub-clusters adjacent to an inactive one), hence we need to count/scan
    56	    // the list and based on weight pick the next sub-cluster.
    57	    Map<SubClusterIdInfo, Float> weights =
    58	        getPolicyInfo().getRouterPolicyWeights();
    59	
    60	    ArrayList<Float> weightList = new ArrayList<>();
    61	    ArrayList<SubClusterId> scIdList = new ArrayList<>();
    62	    for (Map.Entry<SubClusterIdInfo, Float> entry : weights.entrySet()) {
    63	      if (blacklist != null && blacklist.contains(entry.getKey().toId())) {
    64	        continue;
    65	      }
    66	      if (entry.getKey() != null
    67	          && activeSubclusters.containsKey(entry.getKey().toId())) {
    68	        weightList.add(entry.getValue());
    69	        scIdList.add(entry.getKey().toId());
    70	      }
    71	    }
    72	
    73	    int pickedIndex = FederationPolicyUtils.getWeightedRandom(weightList);
    74	    if (pickedIndex == -1) {
    75	      throw new FederationPolicyException(
    76	          "No positive weight found on active subclusters");
    77	    }
    78	    return scIdList.get(pickedIndex);
    79	  }
    80	
    81	}

