43	/**
44	 * This policy selects the subcluster depending on the node where the Client
45	 * wants to run its application.
46	 *
47	 * It succeeds if:
48	 *
49	 * - There are three AMContainerResourceRequests in the order
50	 *   NODE, RACK, ANY
51	 *
52	 * It falls back to WeightedRandomRouterPolicy in case of:
53	 *
54	 * - Null or empty AMContainerResourceRequests;
55	 *
56	 * - One AMContainerResourceRequests and it has ANY as ResourceName;
57	 *
58	 * - The node is in blacklisted SubClusters.
59	 *
60	 * It fails if:
61	 *
62	 * - The node does not exist and RelaxLocality is False;
63	 *
64	 * - We have an invalid number (not 0, 1 or 3) resource requests
65	 */
66	public class LocalityRouterPolicy extends WeightedRandomRouterPolicy {
67	
68	  public static final Logger LOG =
69	      LoggerFactory.getLogger(LocalityRouterPolicy.class);
70	
71	  private SubClusterResolver resolver;
72	  private List<SubClusterId> enabledSCs;
73	
74	  @Override
75	  public void reinitialize(FederationPolicyInitializationContext policyContext)
76	      throws FederationPolicyInitializationException {
77	    super.reinitialize(policyContext);
78	    resolver = policyContext.getFederationSubclusterResolver();
79	    Map<SubClusterIdInfo, Float> weights =
80	        getPolicyInfo().getRouterPolicyWeights();
81	    enabledSCs = new ArrayList<SubClusterId>();
82	    for (Map.Entry<SubClusterIdInfo, Float> entry : weights.entrySet()) {
83	      if (entry != null && entry.getValue() > 0) {
84	        enabledSCs.add(entry.getKey().toId());
85	      }
86	    }
87	  }
88	
89	  @Override
90	  public SubClusterId getHomeSubcluster(
91	      ApplicationSubmissionContext appSubmissionContext,
92	      List<SubClusterId> blackListSubClusters) throws YarnException {
93	
94	    // null checks and default-queue behavior
95	    validate(appSubmissionContext);
96	
97	    List<ResourceRequest> rrList =
98	        appSubmissionContext.getAMContainerResourceRequests();
99	
100	    // Fast path for FailForward to WeightedRandomRouterPolicy
101	    if (rrList == null || rrList.isEmpty() || (rrList.size() == 1
102	        && ResourceRequest.isAnyLocation(rrList.get(0).getResourceName()))) {
103	      return super
104	          .getHomeSubcluster(appSubmissionContext, blackListSubClusters);
105	    }
106	
107	    if (rrList.size() != 3) {
108	      throw new FederationPolicyException(
109	          "Invalid number of resource requests: " + rrList.size());
110	    }
111	
112	    Map<SubClusterId, SubClusterInfo> activeSubClusters =
113	        getActiveSubclusters();
114	    List<SubClusterId> validSubClusters =
115	        new ArrayList<>(activeSubClusters.keySet());
116	    FederationPolicyUtils
117	        .validateSubClusterAvailability(validSubClusters, blackListSubClusters);
118	    if (blackListSubClusters != null) {
119	      // Remove from the active SubClusters from StateStore the blacklisted ones
120	      validSubClusters.removeAll(blackListSubClusters);
121	    }
122	
123	    try {
124	      // With three requests, this has been processed by the
125	      // ResourceRequestInterceptorREST, and should have
126	      // node, rack, and any
127	      SubClusterId targetId = null;
128	      ResourceRequest nodeRequest = null;
129	      ResourceRequest rackRequest = null;
130	      ResourceRequest anyRequest = null;
131	      for (ResourceRequest rr : rrList) {
132	        // Handle "node" requests
133	        try {
134	          targetId = resolver.getSubClusterForNode(rr.getResourceName());
135	          nodeRequest = rr;
136	        } catch (YarnException e) {
137	          LOG.error("Cannot resolve node : {}", e.getLocalizedMessage());
138	        }
139	        // Handle "rack" requests
140	        try {
141	          resolver.getSubClustersForRack(rr.getResourceName());
142	          rackRequest = rr;
143	        } catch (YarnException e) {
144	          LOG.error("Cannot resolve rack : {}", e.getLocalizedMessage());
145	        }
146	        // Handle "ANY" requests
147	        if (ResourceRequest.isAnyLocation(rr.getResourceName())) {
148	          anyRequest = rr;
149	          continue;
150	        }
151	      }
152	      if (nodeRequest == null) {
153	        throw new YarnException("Missing node request");
154	      }
155	      if (rackRequest == null) {
156	        throw new YarnException("Missing rack request");
157	      }
158	      if (anyRequest == null) {
159	        throw new YarnException("Missing any request");
160	      }
161	      LOG.info(
162	          "Node request: " + nodeRequest.getResourceName() + ", Rack request: "
163	              + rackRequest.getResourceName() + ", Any request: " + anyRequest
164	              .getResourceName());
165	      // Handle "node" requests
166	      if (validSubClusters.contains(targetId) && enabledSCs
167	          .contains(targetId)) {
168	        LOG.info("Node {} is in SubCluster: {}", nodeRequest.getResourceName(),
169	            targetId);
170	        return targetId;
171	      } else {
172	        throw new YarnException("The node " + nodeRequest.getResourceName()
173	            + " is in a blacklist SubCluster or not active. ");
174	      }
175	    } catch (YarnException e) {
176	      LOG.error("Validating resource requests failed, Falling back to "
177	          + "WeightedRandomRouterPolicy placement: " + e.getMessage());
178	      // FailForward to WeightedRandomRouterPolicy
179	      // Overwrite request to use a default ANY
180	      ResourceRequest amReq = Records.newRecord(ResourceRequest.class);
181	      amReq.setPriority(appSubmissionContext.getPriority());
182	      amReq.setResourceName(ResourceRequest.ANY);
183	      amReq.setCapability(appSubmissionContext.getResource());
184	      amReq.setNumContainers(1);
185	      amReq.setRelaxLocality(true);
186	      amReq.setNodeLabelExpression(
187	          appSubmissionContext.getNodeLabelExpression());
188	      amReq.setExecutionTypeRequest(
189	          ExecutionTypeRequest.newInstance(ExecutionType.GUARANTEED));
190	      appSubmissionContext
191	          .setAMContainerResourceRequests(Collections.singletonList(amReq));
192	      return super
193	          .getHomeSubcluster(appSubmissionContext, blackListSubClusters);
194	    }
195	  }
196	}
