43	/**
44	 * This class provides a facade to the policy subsystem, and handles the
45	 * lifecycle of policies (e.g., refresh from remote, default behaviors etc.).
46	 */
47	public class RouterPolicyFacade {
48	
49	  private static final Logger LOG =
50	      LoggerFactory.getLogger(RouterPolicyFacade.class);
51	
52	  private final SubClusterResolver subClusterResolver;
53	  private final FederationStateStoreFacade federationFacade;
54	  private Map<String, SubClusterPolicyConfiguration> globalConfMap;
55	
56	  @VisibleForTesting
57	  Map<String, FederationRouterPolicy> globalPolicyMap;
58	
59	  public RouterPolicyFacade(Configuration conf,
60	      FederationStateStoreFacade facade, SubClusterResolver resolver,
61	      SubClusterId homeSubcluster)
62	      throws FederationPolicyInitializationException {
63	
64	    this.federationFacade = facade;
65	    this.subClusterResolver = resolver;
66	    this.globalConfMap = new ConcurrentHashMap<>();
67	    this.globalPolicyMap = new ConcurrentHashMap<>();
68	
69	    // load default behavior from store if possible
70	    String defaultKey = YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY;
71	    SubClusterPolicyConfiguration configuration = null;
72	    try {
73	      configuration = federationFacade.getPolicyConfiguration(defaultKey);
74	    } catch (YarnException e) {
75	      LOG.warn("No fallback behavior defined in store, defaulting to XML "
76	          + "configuration fallback behavior.");
77	    }
78	
79	    // or from XML conf otherwise.
80	    if (configuration == null) {
81	      String defaultFederationPolicyManager =
82	          conf.get(YarnConfiguration.FEDERATION_POLICY_MANAGER,
83	              YarnConfiguration.DEFAULT_FEDERATION_POLICY_MANAGER);
84	      String defaultPolicyParamString =
85	          conf.get(YarnConfiguration.FEDERATION_POLICY_MANAGER_PARAMS,
86	              YarnConfiguration.DEFAULT_FEDERATION_POLICY_MANAGER_PARAMS);
87	      ByteBuffer defaultPolicyParam = ByteBuffer
88	          .wrap(defaultPolicyParamString.getBytes(StandardCharsets.UTF_8));
89	
90	      configuration = SubClusterPolicyConfiguration.newInstance(defaultKey,
91	          defaultFederationPolicyManager, defaultPolicyParam);
92	    }
93	
94	    // construct the required policy manager
95	    FederationPolicyInitializationContext fallbackContext =
96	        new FederationPolicyInitializationContext(configuration,
97	            subClusterResolver, federationFacade, homeSubcluster);
98	    FederationPolicyManager fallbackPolicyManager =
99	        FederationPolicyUtils.instantiatePolicyManager(configuration.getType());
100	    fallbackPolicyManager.setQueue(defaultKey);
101	
102	    // add to the cache the fallback behavior
103	    globalConfMap.put(defaultKey,
104	        fallbackContext.getSubClusterPolicyConfiguration());
105	    globalPolicyMap.put(defaultKey,
106	        fallbackPolicyManager.getRouterPolicy(fallbackContext, null));
107	
108	  }
109	
110	  /**
111	   * This method provides a wrapper of all policy functionalities for routing .
112	   * Internally it manages configuration changes, and policy init/reinit.
113	   *
114	   * @param appSubmissionContext the {@link ApplicationSubmissionContext} that
115	   *          has to be routed to an appropriate subCluster for execution.
116	   *
117	   * @param blackListSubClusters the list of subClusters as identified by
118	   *          {@link SubClusterId} to blackList from the selection of the home
119	   *          subCluster.
120	   *
121	   * @return the {@link SubClusterId} that will be the "home" for this
122	   *         application.
123	   *
124	   * @throws YarnException if there are issues initializing policies, or no
125	   *           valid sub-cluster id could be found for this app.
126	   */
127	  public SubClusterId getHomeSubcluster(
128	      ApplicationSubmissionContext appSubmissionContext,
129	      List<SubClusterId> blackListSubClusters) throws YarnException {
130	
131	    // the maps are concurrent, but we need to protect from reset()
132	    // reinitialization mid-execution by creating a new reference local to this
133	    // method.
134	    Map<String, SubClusterPolicyConfiguration> cachedConfs = globalConfMap;
135	    Map<String, FederationRouterPolicy> policyMap = globalPolicyMap;
136	
137	    if (appSubmissionContext == null) {
138	      throw new FederationPolicyException(
139	          "The ApplicationSubmissionContext " + "cannot be null.");
140	    }
141	
142	    String queue = appSubmissionContext.getQueue();
143	
144	    // respecting YARN behavior we assume default queue if the queue is not
145	    // specified. This also ensures that "null" can be used as a key to get the
146	    // default behavior.
147	    if (queue == null) {
148	      queue = YarnConfiguration.DEFAULT_QUEUE_NAME;
149	    }
150	
151	    // the facade might cache this request, based on its parameterization
152	    SubClusterPolicyConfiguration configuration = null;
153	
154	    try {
155	      configuration = federationFacade.getPolicyConfiguration(queue);
156	    } catch (YarnException e) {
157	      String errMsg = "There is no policy configured for the queue: " + queue
158	          + ", falling back to defaults.";
159	      LOG.warn(errMsg, e);
160	    }
161	
162	    // If there is no policy configured for this queue, fallback to the baseline
163	    // policy that is configured either in the store or via XML config (and
164	    // cached)
165	    if (configuration == null) {
166	      LOG.warn("There is no policies configured for queue: " + queue + " we"
167	          + " fallback to default policy for: "
168	          + YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY);
169	
170	      queue = YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY;
171	      try {
172	        configuration = federationFacade.getPolicyConfiguration(queue);
173	      } catch (YarnException e) {
174	        String errMsg = "Cannot retrieve policy configured for the queue: "
175	            + queue + ", falling back to defaults.";
176	        LOG.warn(errMsg, e);
177	
178	      }
179	    }
180	
181	    // the fallback is not configure via store, but via XML, using
182	    // previously loaded configuration.
183	    if (configuration == null) {
184	      configuration =
185	          cachedConfs.get(YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY);
186	    }
187	
188	    // if the configuration has changed since last loaded, reinit the policy
189	    // based on current configuration
190	    if (!cachedConfs.containsKey(queue)
191	        || !cachedConfs.get(queue).equals(configuration)) {
192	      singlePolicyReinit(policyMap, cachedConfs, queue, configuration);
193	    }
194	
195	    FederationRouterPolicy policy = policyMap.get(queue);
196	    if (policy == null) {
197	      // this should never happen, as the to maps are updated together
198	      throw new FederationPolicyException("No FederationRouterPolicy found "
199	          + "for queue: " + appSubmissionContext.getQueue() + " (for "
200	          + "application: " + appSubmissionContext.getApplicationId() + ") "
201	          + "and no default specified.");
202	    }
203	
204	    return policy.getHomeSubcluster(appSubmissionContext, blackListSubClusters);
205	  }
206	
207	  /**
208	   * This method reinitializes a policy and loads it in the policyMap.
209	   *
210	   * @param queue the queue to initialize a policy for.
211	   * @param conf the configuration to use for initalization.
212	   *
213	   * @throws FederationPolicyInitializationException if initialization fails.
214	   */
215	  private void singlePolicyReinit(Map<String, FederationRouterPolicy> policyMap,
216	      Map<String, SubClusterPolicyConfiguration> cachedConfs, String queue,
217	      SubClusterPolicyConfiguration conf)
218	      throws FederationPolicyInitializationException {
219	
220	    FederationPolicyInitializationContext context =
221	        new FederationPolicyInitializationContext(conf, subClusterResolver,
222	            federationFacade, null);
223	    String newType = context.getSubClusterPolicyConfiguration().getType();
224	    FederationRouterPolicy routerPolicy = policyMap.get(queue);
225	
226	    FederationPolicyManager federationPolicyManager =
227	        FederationPolicyUtils.instantiatePolicyManager(newType);
228	    // set queue, reinit policy if required (implementation lazily check
229	    // content of conf), and cache it
230	    federationPolicyManager.setQueue(queue);
231	    routerPolicy =
232	        federationPolicyManager.getRouterPolicy(context, routerPolicy);
233	
234	    // we need the two put to be atomic (across multiple threads invoking
235	    // this and reset operations)
236	    synchronized (this) {
237	      policyMap.put(queue, routerPolicy);
238	      cachedConfs.put(queue, conf);
239	    }
240	  }
241	
242	  /**
243	   * This method flushes all cached configurations and policies. This should be
244	   * invoked if the facade remains activity after very large churn of queues in
245	   * the system.
246	   */
247	  public synchronized void reset() {
248	
249	    // remember the fallBack
250	    SubClusterPolicyConfiguration conf =
251	        globalConfMap.get(YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY);
252	    FederationRouterPolicy policy =
253	        globalPolicyMap.get(YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY);
254	
255	    globalConfMap = new ConcurrentHashMap<>();
256	    globalPolicyMap = new ConcurrentHashMap<>();
257	
258	    // add to the cache a fallback with keyword null
259	    globalConfMap.put(YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY, conf);
260	    globalPolicyMap.put(YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY,
261	        policy);
262	
263	  }
264	
265	}
