 42	/**
 43	 * Utility class for Federation policy.
 44	 */
 45	@Private
 46	public final class FederationPolicyUtils {
 47	  private static final Logger LOG =
 48	      LoggerFactory.getLogger(FederationPolicyUtils.class);
 49	
 50	  public static final String NO_ACTIVE_SUBCLUSTER_AVAILABLE =
 51	      "No active SubCluster available to submit the request.";
 52	
 53	  private static Random rand = new Random(System.currentTimeMillis());
 54	
 55	  /** Disable constructor. */
 56	  private FederationPolicyUtils() {
 57	  }
 58	
 59	  /**
 60	   * A utilize method to instantiate a policy manager class given the type
 61	   * (class name) from {@link SubClusterPolicyConfiguration}.
 62	   *
 63	   * @param newType class name of the policy manager to create
 64	   * @return Policy manager
 65	   * @throws FederationPolicyInitializationException if fails
 66	   */
 67	  public static FederationPolicyManager instantiatePolicyManager(String newType)
 68	      throws FederationPolicyInitializationException {
 69	    FederationPolicyManager federationPolicyManager = null;
 70	    try {
 71	      // create policy instance and set queue
 72	      Class<?> c = Class.forName(newType);
 73	      federationPolicyManager = (FederationPolicyManager) c.newInstance();
 74	    } catch (ClassNotFoundException e) {
 75	      throw new FederationPolicyInitializationException(e);
 76	    } catch (InstantiationException e) {
 77	      throw new FederationPolicyInitializationException(e);
 78	    } catch (IllegalAccessException e) {
 79	      throw new FederationPolicyInitializationException(e);
 80	    }
 81	    return federationPolicyManager;
 82	  }
 83	
 84	  /**
 85	   * Get Federation policy configuration from state store, using default queue
 86	   * and configuration as fallback.
 87	   *
 88	   * @param queue the queue of the application
 89	   * @param conf the YARN configuration
 90	   * @param federationFacade state store facade
 91	   * @return SubClusterPolicyConfiguration recreated
 92	   */
 93	  public static SubClusterPolicyConfiguration loadPolicyConfiguration(
 94	      String queue, Configuration conf,
 95	      FederationStateStoreFacade federationFacade) {
 96	
 97	    // The facade might cache this request, based on its parameterization
 98	    SubClusterPolicyConfiguration configuration = null;
 99	    if (queue != null) {
100	      try {
101	        configuration = federationFacade.getPolicyConfiguration(queue);
102	      } catch (YarnException e) {
103	        LOG.warn("Failed to get policy from FederationFacade with queue "
104	            + queue + ": " + e.getMessage());
105	      }
106	    }
107	
108	    // If there is no policy configured for this queue, fallback to the baseline
109	    // policy that is configured either in the store or via XML config
110	    if (configuration == null) {
111	      LOG.info("No policy configured for queue {} in StateStore,"
112	          + " fallback to default queue", queue);
113	      queue = YarnConfiguration.DEFAULT_FEDERATION_POLICY_KEY;
114	      try {
115	        configuration = federationFacade.getPolicyConfiguration(queue);
116	      } catch (YarnException e) {
117	        LOG.warn("No fallback behavior defined in store, defaulting to XML "
118	            + "configuration fallback behavior.");
119	      }
120	    }
121	
122	    // or from XML conf otherwise.
123	    if (configuration == null) {
124	      LOG.info("No policy configured for default queue {} in StateStore,"
125	          + " fallback to local config", queue);
126	
127	      String defaultFederationPolicyManager =
128	          conf.get(YarnConfiguration.FEDERATION_POLICY_MANAGER,
129	              YarnConfiguration.DEFAULT_FEDERATION_POLICY_MANAGER);
130	      String defaultPolicyParamString =
131	          conf.get(YarnConfiguration.FEDERATION_POLICY_MANAGER_PARAMS,
132	              YarnConfiguration.DEFAULT_FEDERATION_POLICY_MANAGER_PARAMS);
133	      ByteBuffer defaultPolicyParam = ByteBuffer
134	          .wrap(defaultPolicyParamString.getBytes(StandardCharsets.UTF_8));
135	
136	      configuration = SubClusterPolicyConfiguration.newInstance(queue,
137	          defaultFederationPolicyManager, defaultPolicyParam);
138	    }
139	    return configuration;
140	  }
141	
142	  /**
143	   * Get AMRMProxy policy from state store, using default queue and
144	   * configuration as fallback.
145	   *
146	   * @param queue the queue of the application
147	   * @param oldPolicy the previous policy instance (can be null)
148	   * @param conf the YARN configuration
149	   * @param federationFacade state store facade
150	   * @param homeSubClusterId home sub-cluster id
151	   * @return FederationAMRMProxyPolicy recreated
152	   * @throws FederationPolicyInitializationException if fails
153	   */
154	  public static FederationAMRMProxyPolicy loadAMRMPolicy(String queue,
155	      FederationAMRMProxyPolicy oldPolicy, Configuration conf,
156	      FederationStateStoreFacade federationFacade,
157	      SubClusterId homeSubClusterId)
158	      throws FederationPolicyInitializationException {
159	
160	    // Local policy and its configuration
161	    SubClusterPolicyConfiguration configuration =
162	        loadPolicyConfiguration(queue, conf, federationFacade);
163	
164	    // Instantiate the policyManager and get policy
165	    FederationPolicyInitializationContext context =
166	        new FederationPolicyInitializationContext(configuration,
167	            federationFacade.getSubClusterResolver(), federationFacade,
168	            homeSubClusterId);
169	
170	    LOG.info("Creating policy manager of type: " + configuration.getType());
171	    FederationPolicyManager federationPolicyManager =
172	        instantiatePolicyManager(configuration.getType());
173	    // set queue, reinit policy if required (implementation lazily check
174	    // content of conf), and cache it
175	    federationPolicyManager.setQueue(configuration.getQueue());
176	    return federationPolicyManager.getAMRMPolicy(context, oldPolicy);
177	  }
178	
179	  /**
180	   * Validate if there is any active subcluster that is not blacklisted, it will
181	   * throw an exception if there are no usable subclusters.
182	   *
183	   * @param activeSubClusters the list of subClusters as identified by
184	   *          {@link SubClusterId} currently active.
185	   * @param blackListSubClusters the list of subClusters as identified by
186	   *          {@link SubClusterId} to blackList from the selection of the home
187	   *          subCluster.
188	   * @throws FederationPolicyException if there are no usable subclusters.
189	   */
190	  public static void validateSubClusterAvailability(
191	      List<SubClusterId> activeSubClusters,
192	      List<SubClusterId> blackListSubClusters)
193	      throws FederationPolicyException {
194	    if (activeSubClusters != null && !activeSubClusters.isEmpty()) {
195	      if (blackListSubClusters == null) {
196	        return;
197	      }
198	      for (SubClusterId scId : activeSubClusters) {
199	        if (!blackListSubClusters.contains(scId)) {
200	          // There is at least one active subcluster
201	          return;
202	        }
203	      }
204	    }
205	    throw new FederationPolicyException(
206	        FederationPolicyUtils.NO_ACTIVE_SUBCLUSTER_AVAILABLE);
207	  }
208	
209	  /**
210	   * Select a random bin according to the weight array for the bins. Only bins
211	   * with positive weights will be considered. If no positive weight found,
212	   * return -1.
213	   *
214	   * @param weights the weight array
215	   * @return the index of the sample in the array
216	   */
217	  public static int getWeightedRandom(ArrayList<Float> weights) {
218	    int i;
219	    float totalWeight = 0;
220	    for (i = 0; i < weights.size(); i++) {
221	      if (weights.get(i) > 0) {
222	        totalWeight += weights.get(i);
223	      }
224	    }
225	    if (totalWeight == 0) {
226	      return -1;
227	    }
228	    float samplePoint = rand.nextFloat() * totalWeight;
229	    int lastIndex = 0;
230	    for (i = 0; i < weights.size(); i++) {
231	      if (weights.get(i) > 0) {
232	        if (samplePoint <= weights.get(i)) {
233	          return i;
234	        } else {
235	          lastIndex = i;
236	          samplePoint -= weights.get(i);
237	        }
238	      }
239	    }
240	    // This can only happen if samplePoint is very close to totoalWeight and
241	    // float rounding kicks in during subtractions
242	    return lastIndex;
243	  }
244	
245	  @VisibleForTesting
246	  public static void setRand(long seed){
247	    rand.setSeed(seed);
248	  }
