279	/**
280	 * Base abstract class for a weighted {@link ConfigurableFederationPolicy}.
281	 */
282	public abstract class AbstractConfigurableFederationPolicy
283	    implements ConfigurableFederationPolicy {
284	
285	  private WeightedPolicyInfo policyInfo = null;
286	  private FederationPolicyInitializationContext policyContext;
287	  private boolean isDirty;
288	
289	  public AbstractConfigurableFederationPolicy() {
290	  }
291	
292	  @Override
293	  public void reinitialize(
294	      FederationPolicyInitializationContext initializationContext)
295	      throws FederationPolicyInitializationException {
296	    isDirty = true;
297	    FederationPolicyInitializationContextValidator
298	        .validate(initializationContext, this.getClass().getCanonicalName());
299	
300	    // perform consistency checks
301	    WeightedPolicyInfo newPolicyInfo = WeightedPolicyInfo.fromByteBuffer(
302	        initializationContext.getSubClusterPolicyConfiguration().getParams());
303	
304	    // if nothing has changed skip the rest of initialization
305	    // and signal to childs that the reinit is free via isDirty var.
306	    if (policyInfo != null && policyInfo.equals(newPolicyInfo)) {
307	      isDirty = false;
308	      return;
309	    }
310	
311	    validate(newPolicyInfo);
312	    setPolicyInfo(newPolicyInfo);
313	    this.policyContext = initializationContext;
314	  }
315	
316	  /**
317	   * Overridable validation step for the policy configuration.
318	   *
319	   * @param newPolicyInfo the configuration to test.
320	   *
321	   * @throws FederationPolicyInitializationException if the configuration is not
322	   *           valid.
323	   */
324	  public void validate(WeightedPolicyInfo newPolicyInfo)
325	      throws FederationPolicyInitializationException {
326	    if (newPolicyInfo == null) {
327	      throw new FederationPolicyInitializationException(
328	          "The policy to " + "validate should not be null.");
329	    }
330	  }
331	
332	  /**
333	   * Returns true whether the last reinitialization requires actual changes, or
334	   * was "free" as the weights have not changed. This is used by subclasses
335	   * overriding reinitialize and calling super.reinitialize() to know whether to
336	   * quit early.
337	   *
338	   * @return whether more work is needed to initialize.
339	   */
340	  public boolean getIsDirty() {
341	    return isDirty;
342	  }
343	
344	  /**
345	   * Getter method for the configuration weights.
346	   *
347	   * @return the {@link WeightedPolicyInfo} representing the policy
348	   *         configuration.
349	   */
350	  public WeightedPolicyInfo getPolicyInfo() {
351	    return policyInfo;
352	  }
353	
354	  /**
355	   * Setter method for the configuration weights.
356	   *
357	   * @param policyInfo the {@link WeightedPolicyInfo} representing the policy
358	   *          configuration.
359	   */
360	  public void setPolicyInfo(WeightedPolicyInfo policyInfo) {
361	    this.policyInfo = policyInfo;
362	  }
363	
364	  /**
365	   * Getter method for the {@link FederationPolicyInitializationContext}.
366	   *
367	   * @return the context for this policy.
368	   */
369	  public FederationPolicyInitializationContext getPolicyContext() {
370	    return policyContext;
371	  }
372	
373	  /**
374	   * Setter method for the {@link FederationPolicyInitializationContext}.
375	   *
376	   * @param policyContext the context to assign to this policy.
377	   */
378	  public void setPolicyContext(
379	      FederationPolicyInitializationContext policyContext) {
380	    this.policyContext = policyContext;
381	  }
382	
383	  /**
384	   * This methods gets active subclusters map from the {@code
385	   * FederationStateStoreFacade} and validate it not being null/empty.
386	   *
387	   * @return the map of ids to info for all active subclusters.
388	   *
389	   * @throws YarnException if we can't get the list.
390	   */
391	  protected Map<SubClusterId, SubClusterInfo> getActiveSubclusters()
392	      throws YarnException {
393	
394	    Map<SubClusterId, SubClusterInfo> activeSubclusters =
395	        getPolicyContext().getFederationStateStoreFacade().getSubClusters(true);
396	
397	    if (activeSubclusters == null || activeSubclusters.size() < 1) {
398	      throw new NoActiveSubclustersException(
399	          "Zero active subclusters, cannot pick where to send job.");
400	    }
401	    return activeSubclusters;
402	  }
403	
404	}

