 57	  public static List<ResourceRequest> createResourceRequests(String[] hosts,
 58	      int memory, int vCores, int priority, int containers,
 59	      String labelExpression, boolean relaxLocality) throws YarnException {
 60	    List<ResourceRequest> reqs = new ArrayList<ResourceRequest>();
 61	    for (String host : hosts) {
 62	      ResourceRequest hostReq =
 63	          createResourceRequest(host, memory, vCores, priority, containers,
 64	              labelExpression, relaxLocality);
 65	      reqs.add(hostReq);
 66	      ResourceRequest rackReq =
 67	          createResourceRequest("/default-rack", memory, vCores, priority,
 68	              containers, labelExpression, relaxLocality);
 69	      reqs.add(rackReq);
 70	    }
 71	
 72	    ResourceRequest offRackReq =
 73	        createResourceRequest(ResourceRequest.ANY, memory, vCores, priority,
 74	            containers, labelExpression, relaxLocality);
 75	    reqs.add(offRackReq);
 76	    return reqs;
 77	  }
 78	
 79	  protected static ResourceRequest createResourceRequest(String resource,
 80	      int memory, int vCores, int priority, int containers,
 81	      boolean relaxLocality) throws YarnException {
 82	    return createResourceRequest(resource, memory, vCores, priority, containers,
 83	        null, relaxLocality);
 84	  }
 85	
 86	  @SuppressWarnings("checkstyle:parameternumber")
 87	  public static ResourceRequest createResourceRequest(long id, String resource,
 88	      int memory, int vCores, int priority, int containers,
 89	      String labelExpression, boolean relaxLocality) throws YarnException {
 90	    ResourceRequest out =
 91	        createResourceRequest(resource, memory, vCores, priority, containers,
 92	            labelExpression, relaxLocality);
 93	    out.setAllocationRequestId(id);
 94	    return out;
 95	  }
 96	
 97	  public static ResourceRequest createResourceRequest(String resource,
 98	      int memory, int vCores, int priority, int containers,
 99	      String labelExpression, boolean relaxLocality) throws YarnException {
100	    ResourceRequest req = Records.newRecord(ResourceRequest.class);
101	    req.setResourceName(resource);
102	    req.setNumContainers(containers);
103	    Priority pri = Records.newRecord(Priority.class);
104	    pri.setPriority(priority);
105	    req.setPriority(pri);
106	    Resource capability = Records.newRecord(Resource.class);
107	    capability.setMemorySize(memory);
108	    capability.setVirtualCores(vCores);
109	    req.setCapability(capability);
110	    if (labelExpression != null) {
111	      req.setNodeLabelExpression(labelExpression);
112	    }
113	    req.setRelaxLocality(relaxLocality);
114	    return req;
115	  }
