117	  public static void initializePolicyContext(
118	      FederationPolicyInitializationContext fpc, ConfigurableFederationPolicy
119	      policy, WeightedPolicyInfo policyInfo,
120	      Map<SubClusterId, SubClusterInfo> activeSubclusters, Configuration conf)
121	      throws YarnException {
122	    ByteBuffer buf = policyInfo.toByteBuffer();
123	    fpc.setSubClusterPolicyConfiguration(SubClusterPolicyConfiguration
124	        .newInstance("queue1", policy.getClass().getCanonicalName(), buf));
125	    FederationStateStoreFacade facade = FederationStateStoreFacade
126	        .getInstance();
127	    FederationStateStore fss = mock(FederationStateStore.class);
128	
129	    if (activeSubclusters == null) {
130	      activeSubclusters = new HashMap<SubClusterId, SubClusterInfo>();
131	    }
132	    GetSubClustersInfoResponse response = GetSubClustersInfoResponse
133	        .newInstance(new ArrayList<SubClusterInfo>(activeSubclusters.values()));
134	
135	    when(fss.getSubClusters(any())).thenReturn(response);
136	    facade.reinitialize(fss, conf);
137	    fpc.setFederationStateStoreFacade(facade);
138	    policy.reinitialize(fpc);
139	  }
