162	  /**
163	   * Initialize a {@link SubClusterResolver}.
164	   *
165	   * @return a subcluster resolver for tests.
166	   */
167	  public static SubClusterResolver initResolver() {
168	    YarnConfiguration conf = new YarnConfiguration();
169	    SubClusterResolver resolver =
170	        new DefaultSubClusterResolverImpl();
171	    URL url =
172	        Thread.currentThread().getContextClassLoader().getResource("nodes");
173	    if (url == null) {
174	      throw new RuntimeException(
175	          "Could not find 'nodes' dummy file in classpath");
176	    }
177	    // This will get rid of the beginning '/' in the url in Windows env
178	    File file = new File(url.getPath());
179	
180	    conf.set(YarnConfiguration.FEDERATION_MACHINE_LIST, file.getPath());
181	    resolver.setConf(conf);
182	    resolver.load();
183	    return resolver;
184	  }
