186	  /**
187	   * Initialiaze a main-memory {@link FederationStateStoreFacade} used for
188	   * testing, wiht a mock resolver.
189	   *
190	   * @param subClusterInfos the list of subclusters to be served on
191	   *                        getSubClusters invocations.
192	   *
193	   * @return the facade.
194	   *
195	   * @throws YarnException in case the initialization is not successful.
196	   */
197	
198	  public static FederationStateStoreFacade initFacade(
199	      List<SubClusterInfo> subClusterInfos, SubClusterPolicyConfiguration
200	      policyConfiguration) throws YarnException {
201	    FederationStateStoreFacade goodFacade = FederationStateStoreFacade
202	        .getInstance();
203	    FederationStateStore fss = mock(FederationStateStore.class);
204	    GetSubClustersInfoResponse response = GetSubClustersInfoResponse
205	        .newInstance(subClusterInfos);
206	    when(fss.getSubClusters(any())).thenReturn(response);
207	
208	    List<SubClusterPolicyConfiguration> configurations = new ArrayList<>();
209	    configurations.add(policyConfiguration);
210	
211	    GetSubClusterPoliciesConfigurationsResponse policiesResponse =
212	        GetSubClusterPoliciesConfigurationsResponse
213	            .newInstance(configurations);
214	    when(fss.getPoliciesConfigurations(any())).thenReturn(policiesResponse);
215	
216	    GetSubClusterPolicyConfigurationResponse policyResponse =
217	        GetSubClusterPolicyConfigurationResponse
218	            .newInstance(policyConfiguration);
219	    when(fss.getPolicyConfiguration(any())).thenReturn(policyResponse);
220	
221	    goodFacade.reinitialize(fss, new Configuration());
222	    return goodFacade;
223	  }
